INSERT INTO `admin_word_book` (`code`,`name`,`description`,`word_count`,`language_code`,`category_code`,`status`,`ext_info`) VALUES ('BEC_2','商务英语词汇','精选商务英语初级、中级、高级考试及实际应用词汇。通过科学频率算法筛选高频核心词汇，专业团队把关，帮助用户节约时间、高效学习。精选例句和词组短语，帮助用户准确把握用词含义，快速掌握真实场景的运用。结合背单词科学记忆方法，有利于用户迅速掌握商务词汇，有效扩大词汇量，提高考试成绩。适用于备战考试，有意丰富自身商务英语词汇的用户。',2753,'EN','UNIVERSITY',1,'{"sourceId": "BEC_2", "cover": "https://nos.netease.com/ydschool-online/youdao_BEC_2.jpg", "introduce": "精选商务英语初级、中级、高级考试及实际应用词汇。通过科学频率算法筛选高频核心词汇，专业团队把关，帮助用户节约时间、高效学习。精选例句和词组短语，帮助用户准确把握用词含义，快速掌握真实场景的运用。结合背单词科学记忆方法，有利于用户迅速掌握商务词汇，有效扩大词汇量，提高考试成绩。适用于备战考试，有意丰富自身商务英语词汇的用户。", "version": "2", "size": 1494016, "reciteUserNum": 300528, "bookOrigin": {"originUrl": "", "desc": "来源于", "originName": "有道词典"}, "tags": ["BEC"], "offlinedata": "http://ydschool-online.nos.netease.com/1521164626760_BEC_2.zip"}') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`word_count`=VALUES(`word_count`),`language_code`=VALUES(`language_code`),`category_code`=VALUES(`category_code`),`status`=VALUES(`status`),`ext_info`=VALUES(`ext_info`);
