INSERT INTO `admin_word_book` (`code`,`name`,`description`,`word_count`,`language_code`,`category_code`,`status`,`ext_info`) VALUES ('CET4_1','四级真题核心词（正序版）','有道超强词频统计，考神团队精心制作。整合历届大学英语四级真题中出现的所有单词，将3739个四级词汇通过科学的频率算法，考神团队专业把控，筛选至考试必背的1162个核心词汇。搭配背单词近十年真题例句，感受最真实的考试情境，在语境中加深理解。面包君带你用最短的时间考最高的分数！适用于考生备战考试、用户高效学习。',1162,'EN','UNIVERSITY',1,'{"sourceId": "CET4_1", "cover": "https://nos.netease.com/ydschool-online/1491037568440CET4_1.jpg", "introduce": "有道超强词频统计，考神团队精心制作。整合历届大学英语四级真题中出现的所有单词，将3739个四级词汇通过科学的频率算法，考神团队专业把控，筛选至考试必背的1162个核心词汇。搭配背单词近十年真题例句，感受最真实的考试情境，在语境中加深理解。面包君带你用最短的时间考最高的分数！适用于考生备战考试、用户高效学习。", "version": "3", "size": 764018, "reciteUserNum": 6324, "bookOrigin": {"originUrl": "", "desc": "来源于", "originName": "有道考神团队"}, "tags": ["有道"], "offlinedata": "http://ydschool-online.nos.netease.com/1521164649209_CET4_1.zip"}') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`word_count`=VALUES(`word_count`),`language_code`=VALUES(`language_code`),`category_code`=VALUES(`category_code`),`status`=VALUES(`status`),`ext_info`=VALUES(`ext_info`);
