INSERT INTO `admin_word_book` (`code`,`name`,`description`,`word_count`,`language_code`,`category_code`,`status`,`ext_info`) VALUES ('KAOYAN_1','考研必考词汇（正序版）','有道超强词频统计，考神团队精心制作。严格按照考研英语最新大纲要求，运用科学的统计算法，考神团队深入研究历年真题及考研英语命题规律，对考研英语词汇进行深入地分析和研究，统计真实考试场景下的必背词汇，名师把关剔除简单词汇，将4533个考研词汇通过严格科学的方法筛选至1341个核心词，帮助考生省时省力完成备考，快速高效！',1341,'EN','KAOYAN',1,'{"sourceId": "KaoYan_1", "cover": "https://nos.netease.com/ydschool-online/1491037662208KaoYan_1.jpg", "introduce": "有道超强词频统计，考神团队精心制作。严格按照考研英语最新大纲要求，运用科学的统计算法，考神团队深入研究历年真题及考研英语命题规律，对考研英语词汇进行深入地分析和研究，统计真实考试场景下的必背词汇，名师把关剔除简单词汇，将4533个考研词汇通过严格科学的方法筛选至1341个核心词，帮助考生省时省力完成备考，快速高效！", "version": "2", "size": 685507, "reciteUserNum": 7621, "bookOrigin": {"originUrl": "", "desc": "来源于", "originName": "有道考神团队"}, "tags": ["考研", "有道"], "offlinedata": "http://ydschool-online.nos.netease.com/1521164669833_KaoYan_1.zip"}') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`word_count`=VALUES(`word_count`),`language_code`=VALUES(`language_code`),`category_code`=VALUES(`category_code`),`status`=VALUES(`status`),`ext_info`=VALUES(`ext_info`);
