INSERT INTO `admin_word_book` (`code`,`name`,`description`,`word_count`,`language_code`,`category_code`,`status`,`ext_info`) VALUES ('SAT_2','SAT词汇','全面收录SAT考试词汇4423个，有道词典提供正版权威词库，参考College Board官方推荐权威辞典给出的单词释意及例句，帮助考生在语境中加深对单词的理解，更有针对性地备考。每个单词均列出短语和多项近义词，帮助考生掌握词汇实际运用方法，应对一词多义、一次多用的情况。适合准备SAT考试的用户以及英语学习爱好者。',4423,'EN','OVERSEAS',1,'{"sourceId": "SAT_2", "cover": "https://nos.netease.com/ydschool-online/youdao_SAT_2.jpg", "introduce": "全面收录SAT考试词汇4423个，有道词典提供正版权威词库，参考College Board官方推荐权威辞典给出的单词释意及例句，帮助考生在语境中加深对单词的理解，更有针对性地备考。每个单词均列出短语和多项近义词，帮助考生掌握词汇实际运用方法，应对一词多义、一次多用的情况。适合准备SAT考试的用户以及英语学习爱好者。", "version": "2", "size": 1784650, "reciteUserNum": 13876, "bookOrigin": {"originUrl": "", "desc": "来源于", "originName": "有道词典"}, "tags": ["SAT", "有道"], "offlinedata": "http://ydschool-online.nos.netease.com/1521164670910_SAT_2.zip"}') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`word_count`=VALUES(`word_count`),`language_code`=VALUES(`language_code`),`category_code`=VALUES(`category_code`),`status`=VALUES(`status`),`ext_info`=VALUES(`ext_info`);
