INSERT INTO `admin_word_book` (`code`,`name`,`description`,`word_count`,`language_code`,`category_code`,`status`,`ext_info`) VALUES ('TOEFL_2','TOEFL词汇','整合收录托福考试指南、TPO真题词汇共9213个单词。有道词典提供正版权威词库，国外权威辞典例句和英文释意，帮助用户把握词汇命脉，在学习过程中更好地理解词汇原汁原味的含义。每个单词均列出短语和多项近义词，有效扩展词汇量并提高记忆效率，帮助用户从容应对词汇难度和用法都更具挑战性的托福考试。适合准备托福考试，想要提高英语能力的用户。',9213,'EN','OVERSEAS',1,'{"sourceId": "TOEFL_2", "cover": "https://nos.netease.com/ydschool-online/youdao_TOEFL_2.jpg", "introduce": "整合收录托福考试指南、TPO真题词汇共9213个单词。有道词典提供正版权威词库，国外权威辞典例句和英文释意，帮助用户把握词汇命脉，在学习过程中更好地理解词汇原汁原味的含义。每个单词均列出短语和多项近义词，有效扩展词汇量并提高记忆效率，帮助用户从容应对词汇难度和用法都更具挑战性的托福考试。适合准备托福考试，想要提高英语能力的用户。", "version": "2", "size": 4327321, "reciteUserNum": 118896, "bookOrigin": {"originUrl": "", "desc": "来源于", "originName": "有道词典"}, "tags": ["TOEFL", "有道"], "offlinedata": "http://ydschool-online.nos.netease.com/1521164640451_TOEFL_2.zip"}') ON DUPLICATE KEY UPDATE `name`=VALUES(`name`),`description`=VALUES(`description`),`word_count`=VALUES(`word_count`),`language_code`=VALUES(`language_code`),`category_code`=VALUES(`category_code`),`status`=VALUES(`status`),`ext_info`=VALUES(`ext_info`);
